export const tailMeasureDefinitions={
 tailMeasures:{title:'Inspect an invented five-state loss distribution and its exact upper-tail measures',fields:[
  ['tailCapital','Opening investment used to translate returns into loss dollars (CAD)',100000,1000,1000000,1000],
  ['tailConfidence','Cumulative probability used for the loss quantile (%)',95,80,99,.5],
  ['tailLossScale','Multiplier on the three loss-state sizes (%)',100,50,150,10]
 ]}
};
export function tailMeasurePlan(d){
 const outcomes=[[40,1],[20,4],[5,15],[-5,40],[-12,40]].map(([baseLoss,massPercent])=>{const lossPercent=baseLoss>0?baseLoss*d.tailLossScale/100:baseLoss;return {lossPercent,massPercent,loss:d.tailCapital*lossPercent/100};});
 let cumulative=0,valueAtRisk;
 for(const row of [...outcomes].sort((a,b)=>a.loss-b.loss)){cumulative+=row.massPercent;if(cumulative>=d.tailConfidence){valueAtRisk=row.loss;break;}}
 if(valueAtRisk===undefined)throw Error('The stated distribution has no requested quantile.');
 const tailPercent=100-d.tailConfidence,slices=[];let remaining=tailPercent;
 for(const row of [...outcomes].sort((a,b)=>b.loss-a.loss)){
  if(remaining<=0)break;const massTaken=Math.min(remaining,row.massPercent);remaining-=massTaken;
  if(massTaken>0)slices.push({...row,massTaken,tailWeight:massTaken/tailPercent,contribution:row.loss*massTaken/tailPercent});
 }
 return {outcomes,valueAtRisk,tailPercent,slices,expectedShortfall:slices.reduce((s,r)=>s+r.contribution,0),maxLoss:Math.max(...outcomes.map(r=>r.loss)),strictBeyondPercent:outcomes.filter(r=>r.loss>valueAtRisk).reduce((s,r)=>s+r.massPercent,0)};
}
export function tailMeasureResult(kind,d){
 if(kind!=='tailMeasures')throw Error('Unknown loss-tail-measure topic.');
 const p=tailMeasurePlan(d),percent=n=>Number(n.toFixed(4))+'%';
 return {metrics:[['Loss quantile at '+d.tailConfidence+'% cumulative probability (VaR)',p.valueAtRisk,'money'],['Average loss in the worst '+percent(p.tailPercent)+' of model probability (ES)',p.expectedShortfall,'money'],['Largest loss among the five invented outcomes',p.maxLoss,'money']],note:'Original, completely specified one-year probability model with five mutually exclusive outcomes. Baseline simple returns are −40%, −20%, −5%, +5% and +12%, with assumed probabilities 1%, 4%, 15%, 40% and 40%. The scale changes only the three loss sizes; gain outcomes and all probabilities remain fixed. These are chosen numbers, not market observations, estimated frequencies or forecasts. Positive loss means a decline; negative loss means a gain. VaR is the smallest loss value whose cumulative probability is at least the selected level, with no floor at zero. ES averages exactly the worst remaining probability mass, taking only the needed fraction of a boundary state. Confidence here is a cumulative model probability, not a statistical confidence interval. No normality, sample, p-value, simulation, serial returns, leverage, fees, taxes, cash flows or regulatory-capital calculation is used. The largest modeled loss is only a bound of these five invented outcomes and is not an actual investment’s maximum loss. These risk summaries do not determine a sufficient cash reserve or the probability of meeting a household goal.',charts:[
  {id:'tail-measures-outcome-probabilities',type:'bar',title:'State every possible return and its assumed probability before calculating a risk summary',unit:'percent',unitLabel:'Assumed probability in one invented holding year · labels give the return',rows:p.outcomes.map(r=>({label:'Return '+(r.lossPercent>0?'−':'+')+percent(Math.abs(r.lossPercent)),value:r.massPercent/100})),note:'Each return is a separate complete outcome. The five probabilities sum to 100%. A bar’s length represents probability, not the size of its loss. Changing opening capital scales dollar losses without changing these probabilities.'},
  {id:'tail-measures-three-summaries',type:'signedbar',title:'A loss quantile, a tail average and the largest modeled loss answer different questions',unit:'money',unitLabel:'CAD loss · negative means a gain · one-year model',rows:[{label:'VaR: selected loss quantile',value:p.valueAtRisk},{label:'ES: selected tail average',value:p.expectedShortfall},{label:'Largest loss among five states',value:p.maxLoss}],note:'VaR is a threshold in the specified cumulative distribution, rather than the maximum possible loss. ES is an average over the selected worst probability mass and can also be exceeded. The largest state loss is known only because this toy model specifies every state. None is an independently estimated market-risk forecast.'},
  {id:'tail-measures-average-bridge',type:'waterfall',title:'Build expected shortfall from probability weights inside exactly the selected tail',unit:'money',rows:p.slices.map(r=>({label:percent(r.lossPercent)+' loss · '+percent(r.tailWeight*100)+' of tail',value:r.contribution})),totalLabel:'Expected shortfall: tail average',note:'Each step equals a state’s dollar loss multiplied by its share of the selected tail. The shares sum to 100% of that tail. A boundary state can contribute only part of its original probability mass; this does not split or partly reimburse an actual loss. The steps add to an average loss, not a bill combining multiple mutually exclusive outcomes.'},
  {id:'tail-measures-confidence-severity',type:'heatmap',title:'Tail averages change when the chosen probability tail or loss sizes change',unit:'money',unitLabel:'CAD expected shortfall · rows: cumulative quantile level; columns: loss-size multiplier',columns:['50%','100%','125%','150%'],rows:[80,90,95,99].map(tailConfidence=>({label:tailConfidence+'% level',values:[50,100,125,150].map(tailLossScale=>tailMeasurePlan({...d,tailConfidence,tailLossScale}).expectedShortfall)})),note:'Every cell retains opening capital and the five assumed probabilities. It changes the selected quantile level and the sizes of the three loss states; it does not change the two gain states. A higher level averages a smaller, more severe tail in this example. The grid does not estimate probabilities, validate a portfolio model or prescribe a reserve.'}
 ]};
}
